iewed_by","reviewed_by_email","reviewed_at","review_notes"],"triggers":[{"name":"inventory_location_change_apply","enabled":"O"},{"name":"inventory_location_change_audit","enabled":"O"}]},{"schema":"public","name":"inventory_photo_hotspots","primaryKey":["id"],"columns":["id","department_id","apparatus_id","photo_view_id","compartment_id","label","x_basis_points","y_basis_points","display_order","created_by","created_at"],"triggers":[]},{"schema":"public","name":"inventory_readiness_exceptions","primaryKey":["id"],"columns":["id","department_id","apparatus_id","equipment_id","check_item_id","result","priority","notes","status","out_of_service","opened_by","opened_at","resolved_at","issue_categories","assigned_employee_ids","assigned_employee_names","evidence_photo_id","resolved_by","resolution_notes"],"triggers":[{"name":"operational_change","enabled":"O"}]},{"schema":"public","name":"inventory_work_orders","primaryKey":["id"],"columns":["id","department_id","apparatus_id","equipment_id","status","priority","summary","details","assigned_to","opened_by","opened_at","due_at","closed_at","linked_exception_id","assigned_employee_ids","assigned_employee_names","repair_date","repair_cost","vendor","invoice_number","resolution_notes","closed_by","service_type","odometer","labor_hours","performed_by","parts_used","next_service_due_date","next_service_due_mileage"],"triggers":[]},{"schema":"firehouse","name":"field_preplan_alerts","primaryKey":["id"],"columns":["id","preplan_id","level_id","space_id","alert_type","title","instructions","severity","display_order","pin_to_respond","effective_at","expires_at","expiration_action","verification_required","verified_by","verified_at","archived","created_by","created_at","updated_by","updated_at"],"triggers":[{"name":"operational_change","enabled":"O"}]},{"schema":"firehouse","name":"field_preplan_annotations","primaryKey":["id"],"columns":["id","preplan_id","level_id","annotation_type","operational_subtype","name","label","geometry","coordinate_space","line_color","fill_color","line_width","opacity","font_size","rotation","arrow_config","measurement","units","sort_order","min_zoom","max_zoom","effective_at","expires_at","expiration_action","verified_by","verified_at","archived","created_by","created_at","updated_by","updated_at"],"triggers":[]},{"schema":"firehouse","name":"field_preplan_features","primaryKey":["id"],"columns":["id","preplan_id","feature_type","label","latitude","longitude","system_type","service_status","details","created_by","created_at","updated_at","primary_level_id","mapped","operational_category","severity","display_priority","min_zoom","max_zoom","effective_at","expires_at","expiration_action","verified_by","verified_at","structured_metadata","plan_x","plan_y","updated_by"],"triggers":[{"name":"operational_change","enabled":"O"}]},{"schema":"firehouse","name":"field_preplan_hazmat","primaryKey":["id"],"columns":["id","preplan_id","level_id","space_id","mapped","chemical_name","un_na_number","erg_guide_number","quantity","quantity_unit","container_type","physical_state","exact_location","nfpa_health","nfpa_flammability","nfpa_instability","nfpa_special","date_verified","verified_by","effective_at","expires_at","expiration_action","notes","latitude","longitude","plan_x","plan_y","archived","created_by","created_at","updated_by","updated_at"],"triggers":[{"name":"operational_change","enabled":"O"}]},{"schema":"firehouse","name":"field_preplan_hazmat_zones","primaryKey":["id"],"columns":["id","preplan_id","hazmat_id","level_id","zone_type","geometry_type","geometry","label","radius_feet","fill_color","line_color","opacity","line_width","line_style","effective_at","expires_at","archived","created_by","created_at","updated_by","updated_at"],"triggers":[{"name":"operational_change","enabled":"O"}]},{"schema":"firehouse","name":"field_preplan_hose_lays","primaryKey":["id"],"columns":["id","preplan_id","level_id","name","source_hydrant_id","destination_side","destination_feature_id","path","segment_distances","total_distance_feet","hose_size_inches","section_length_feet","reserve_feet","recommended_hose_feet","supply_line_label","apparatus_id","apparatus_capacity_feet","inventory_verified_at","notes","archived","created_by","created_at","updated_by","updated_at"],"triggers":[{"name":"operational_change","enabled":"O"}]},{"schema":"firehouse","name":"safety_inspection_results","primaryKey":["id"],"columns":["id","inspection_id","template_item_id","snapshot_section_name","snapshot_label","snapshot_equipment_type","snapshot_required","snapshot_sort_order","result_status","deficiency_note","corrected_on_site","updated_by","updated_at"],"triggers":[]},{"schema":"firehouse","name":"station_ot_interest","primaryKey":["id"],"columns":["id","slot_id","employee_id","response","responded_at"],"triggers":[]},{"schema":"firehouse","name":"station_ot_offers","primaryKey":["id"],"columns":["id","slot_id","employee_id","mode","status","rank","offered_at","responded_at"],"triggers":[]},{"schema":"firehouse","name":"station_shift_claims","primaryKey":["id"],"columns":["id","slot_id","role","employee_id","note","status","created_at","reviewed_by","reviewed_at","reminder_changed_at"],"triggers":[{"name":"scheduler_claim_changed","enabled":"O"},{"name":"scheduler_claim_deadline_guard","enabled":"O"}]},{"schema":"public","name":"inventory_work_order_documents","primaryKey":["id"],"columns":["id","department_id","apparatus_id","work_order_id","document_type","object_key","original_filename","mime_type","byte_size","note","uploaded_by","uploaded_at"],"triggers":[]},{"schema":"firehouse","name":"field_preplan_assets","primaryKey":["id"],"columns":["id","preplan_id","feature_id","hazmat_id","level_id","category","original_filename","object_key","mime_type","file_size","caption","description","sort_order","pin_to_respond","version","archived","created_by","created_at","updated_by","updated_at"],"triggers":[{"name":"operational_change","enabled":"O"}]},{"schema":"firehouse","name":"field_preplan_feature_levels","primaryKey":["feature_id","level_id"],"columns":["feature_id","level_id","is_primary","created_at"],"triggers":[]},{"schema":"firehouse","name":"field_preplan_photo_annotations","primaryKey":["id"],"columns":["id","asset_id","annotation_type","geometry","label","style","sort_order","created_by","created_at","updated_by","updated_at"],"triggers":[]}]'::jsonb;
  item jsonb;
  payload jsonb;
  identity_record jsonb;
  trigger_record jsonb;
  rows_json text;
  statement text;
  conflict_clause text;
  key_columns text;
  changed_columns text;
  actual_count bigint;
  actual_hash text;
  table_verification jsonb := '[]'::jsonb;
  enable_command text;
BEGIN
  SELECT * INTO STRICT run FROM private.review_import_runs WHERE id=p_run FOR UPDATE;
  IF run.status='complete' THEN RETURN run.verification; END IF;
  IF run.target_project<>'qizfnynrspsydiuwkkex' OR p_passphrase IS NULL OR length(p_passphrase)<64 THEN RAISE EXCEPTION 'Independent review restore configuration required'; END IF;
  IF EXISTS(SELECT 1 FROM public.portal_pin_credentials) THEN RAISE EXCEPTION 'Restore must finish before member PIN activation'; END IF;
  IF (SELECT count(*) FROM private.review_import_chunks WHERE run_id=p_run)<>run.parts
    OR (SELECT min(part_number) FROM private.review_import_chunks WHERE run_id=p_run)<>0
    OR (SELECT max(part_number) FROM private.review_import_chunks WHERE run_id=p_run)<>run.parts-1 THEN RAISE EXCEPTION 'Snapshot chunks are incomplete'; END IF;
  SELECT string_agg(data,''::bytea ORDER BY part_number) INTO cipher FROM private.review_import_chunks WHERE run_id=p_run;
  IF octet_length(cipher)<>run.byte_size OR encode(extensions.digest(cipher,'sha256'),'hex')<>run.cipher_sha256 THEN RAISE EXCEPTION 'Snapshot integrity check failed'; END IF;
  snapshot := extensions.pgp_sym_decrypt(cipher,p_passphrase)::jsonb;
  IF snapshot->>'source_project'<>run.source_project OR (SELECT count(*) FROM jsonb_object_keys(snapshot->'tables'))<>jsonb_array_length(plan) THEN RAISE EXCEPTION 'Snapshot source or table plan does not match'; END IF;
  FOR identity_record IN SELECT value FROM jsonb_array_elements(snapshot->'identities') LOOP
    IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=(identity_record->>'id')::uuid AND lower(u.email)=lower(identity_record->>'email')) THEN RAISE EXCEPTION 'A historical identity must be provisioned before restore'; END IF;
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(plan) LOOP
    payload := snapshot->'tables'->((item->>'schema')||'.'||(item->>'name'));
    IF payload IS NULL OR jsonb_typeof(payload->'rows')<>'array' OR jsonb_array_length(payload->'rows')<>(payload->>'count')::bigint THEN RAISE EXCEPTION 'Invalid snapshot table %',item->>'name'; END IF;
    SELECT '['||coalesce(string_agg(value,',' ORDER BY ord),'')||']' INTO rows_json FROM jsonb_array_elements_text(payload->'rows') WITH ORDINALITY AS row_values(value,ord);
    conflict_clause := '';
    IF jsonb_array_length(item->'primaryKey')>0 THEN
      SELECT string_agg(format('%I',value),',') INTO key_columns FROM jsonb_array_elements_text(item->'primaryKey');
      SELECT string_agg(format('%I=excluded.%I',value,value),',') INTO changed_columns FROM jsonb_array_elements_text(item->'columns') WHERE NOT (item->'primaryKey') ? value;
      conflict_clause := format(' ON CONFLICT (%s) DO ',key_columns)||CASE WHEN changed_columns IS NULL THEN 'NOTHING' ELSE 'UPDATE SET '||changed_columns END;
    ELSE
      EXECUTE format('SELECT count(*) FROM %I.%I',item->>'schema',item->>'name') INTO actual_count;
      IF actual_count<>0 THEN RAISE EXCEPTION 'A table without a primary key must be empty before restore: %',item->>'name'; END IF;
    END IF;
    -- Suspend application notifications/audit writers only inside this atomic
    -- restore. PostgreSQL foreign-key constraints and RLS remain in place.
    EXECUTE format('ALTER TABLE %I.%I DISABLE TRIGGER USER',item->>'schema',item->>'name');
    statement := format('INSERT INTO %I.%I SELECT * FROM jsonb_populate_recordset(NULL::%I.%I,%L::jsonb)',item->>'schema',item->>'name',item->>'schema',item->>'name',rows_json)||conflict_clause;
    EXECUTE statement;
    FOR trigger_record IN SELECT value FROM jsonb_array_elements(item->'triggers') LOOP
      enable_command := CASE trigger_record->>'enabled' WHEN 'O' THEN 'ENABLE' WHEN 'D' THEN 'DISABLE' WHEN 'R' THEN 'ENABLE REPLICA' WHEN 'A' THEN 'ENABLE ALWAYS' ELSE NULL END;
      IF enable_command IS NULL THEN RAISE EXCEPTION 'Unrecognized source trigger state'; END IF;
      EXECUTE format('ALTER TABLE %I.%I %s TRIGGER %I',item->>'schema',item->>'name',enable_command,trigger_record->>'name');
    END LOOP;
    EXECUTE format('SELECT count(*),encode(extensions.digest(coalesce(string_agg(row_json,E''\n'' ORDER BY row_json),''''),''sha256''),''hex'') FROM (SELECT to_jsonb(t)::text AS row_json FROM %I.%I t) actual_rows',item->>'schema',item->>'name') INTO actual_count,actual_hash;
    IF actual_count<>(payload->>'count')::bigint OR actual_hash<>payload->>'sha256' THEN RAISE EXCEPTION 'Restored count or hash differs for %.%',item->>'schema',item->>'name'; END IF;
    table_verification := table_verification||jsonb_build_array(jsonb_build_object('table',(item->>'schema')||'.'||(item->>'name'),'rows',actual_count::text,'sha256',actual_hash));
  END LOOP;
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_constraint c JOIN pg_catalog.pg_namespace n ON n.oid=c.connamespace WHERE n.nspname IN ('public','firehouse') AND NOT c.convalidated) THEN RAISE EXCEPTION 'An unvalidated constraint remains'; END IF;
  UPDATE private.review_import_runs SET status='complete',restored_at=now(),verification=jsonb_build_object('captured_at',snapshot->>'captured_at','tables',table_verification,'foreign_keys','enforced throughout restore') WHERE id=p_run;
  RETURN (SELECT r.verification FROM private.review_import_runs r WHERE r.id=p_run);
END;
$restore$;
REVOKE ALL ON FUNCTION private.restore_review_snapshot(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
